from __future__ import annotations

def normalize_word(st: str) -> str:
    return ''.join((c.lower() for c in st if c.isalpha()))

def calculate_score(word: str, dict_scores: dict) -> int:
    word = normalize_word(word)
    score = 0
    for char in word:
        score += dict_scores.get(char, 0)
    return score

def scrabble_score(st: str) -> int:
    return calculate_score(st, dict_scores)

