def is_valid_roll(dice, k):
    return sum(dice) == k

def generate_rolls(n, s):
    if n == 0:
        return [[]]
    if s == 0:
        return []
    rolls = []
    for i in range(1, s + 1):
        for roll in generate_rolls(n - 1, s):
            rolls.append([i] + roll)
    return rolls

def count_valid_rolls(n, s, k):
    rolls = generate_rolls(n, s)
    valid_rolls = [roll for roll in rolls if is_valid_roll(roll, k)]
    return len(valid_rolls)

def outcome(n, s, k):
    return count_valid_rolls(n, s, k)

