def count_combinations(n, s, k):
    if n == 0:
        return 0
    if k == 0:
        return 1
    count = 0
    for i in range(1, min(s, k) + 1):
        count += count_combinations(n - 1, s, k - i)
    return count

def outcome(n, s, k):
    return count_combinations(n, s, k)

