from __future__ import annotations

def calculate_loneliness(number, index):
    digits = [int(d) for d in str(number)]
    left_sum = sum(digits[:index]) if index > 0 else 0
    right_sum = sum(digits[index + 1:]) if index < len(digits) - 1 else 0
    return left_sum + right_sum

def find_minimal_loneliness_ones(number):
    ones_positions = [i for i, digit in enumerate(str(number)) if digit == '1']
    if not ones_positions:
        return False
    min_loneliness = float('inf')
    for pos in ones_positions:
        loneliness = calculate_loneliness(number, pos)
        if loneliness < min_loneliness:
            min_loneliness = loneliness
    return min_loneliness == calculate_loneliness(number, ones_positions[0])

def loneliest(number):
    ones = find_minimal_loneliness_ones(number)
    if not ones:
        return False
    min_loneliness = min(ones.values())
    return min_loneliness == 2

