def is_valid_roman(s: str) -> bool:
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50}
    prev_value = 0
    total = 0
    for char in reversed(s):
        value = roman_map[char]
        if value >= prev_value:
            total += value
        else:
            total -= value
        prev_value = value
    return total > 0 and s[0] != 'I'

