def is_water_related(word: str) -> bool:
    return any((word.lower().endswith(suffix) for suffix in ('water', 'wet', 'wash')))

def is_slime_related(word: str) -> bool:
    return 'slime' in word.lower()

def bucket_of(said: str) -> str:
    words = said.lower().split()
    water_related = any((is_water_related(word) for word in words))
    slime_related = any((is_slime_related(word) for word in words))
    if water_related and slime_related:
        return 'sludge'
    elif water_related:
        return 'water'
    elif slime_related:
        return 'slime'
    else:
        return 'air'

