def is_valid_number(num: str) -> bool:
    return num.isdigit() and 0 <= int(num) <= 9

def calculate_average(numbers: list[int]) -> int:
    if not numbers:
        return 0
    return sum(numbers) // len(numbers)

def convert_to_number(num_str: str) -> int:
    if not is_valid_number(num_str):
        raise ValueError('Invalid number')
    return int(num_str)

def average_string(s: str) -> str:
    if not s:
        return 'n/a'
    numbers = s.split()
    converted_numbers = [convert_to_number(num) for num in numbers]
    if any((num > 9 for num in converted_numbers)):
        return 'n/a'
    average = calculate_average(converted_numbers)
    return str(average)

