def convert_to_number(word):
    number_map = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    return number_map.get(word, None)

def calculate_average(numbers):
    if not numbers:
        return 'n/a'
    total = 0
    count = 0
    for number in numbers:
        try:
            num = convert_to_number(number)
            if num > 9:
                return 'n/a'
            total += num
            count += 1
        except ValueError:
            return 'n/a'
    if count == 0:
        return 'n/a'
    average = total // count
    return average

def average_string(s):
    if not s:
        return 'n/a'
    numbers = []
    for word in s.split():
        if word.isdigit() and 0 <= int(word) <= 9:
            numbers.append(int(word))
        else:
            return 'n/a'
    if not numbers:
        return 'n/a'
    average = calculate_average(numbers)
    return str(average)

