def is_uppercase(char: str) -> bool:
    return char.isupper()

def convert_to_lowercase(char: str) -> str:
    return char.lower()

def kebabize(string: str) -> str:
    result = []
    for char in string:
        if is_uppercase(char):
            result.append('-')
        result.append(convert_to_lowercase(char))
    return ''.join(result).lstrip('-')

