def find_cats(yard):
    cat_positions = []
    for i in range(len(yard)):
        for j in range(len(yard[i])):
            if yard[i][j] in 'LMR':
                cat_positions.append((i, j))
    return cat_positions

def calculate_distance(pos1, pos2):
    x1, y1 = pos1
    x2, y2 = pos2
    return ((x2 - x1) ** 2 + (y2 - y1) ** 2) ** 0.5

def check_distances(cat_positions, min_distance):
    distances = []
    for i in range(len(cat_positions)):
        for j in range(i + 1, len(cat_positions)):
            if cat_positions[i] != '-' and cat_positions[j] != '-':
                pos1 = (i, j)
                pos2 = (i, j)
                distance = calculate_distance(pos1, pos2)
                distances.append(distance)
    return all((d >= min_distance for d in distances))

def peaceful_yard(yard, min_distance):
    cat_positions = find_cats(yard)
    return check_distances(cat_positions, min_distance)

